    #[test]
    fn kept_short_replay_preserves_observed_competitors_and_rejects_tampering() {
        let root = std::env::temp_dir().join(format!(
            "orgraft_kept_short_{}_{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        fs::create_dir_all(&root).unwrap();
        let mut source = PolishPaths::at_round_dir(
            &root,
            "mito",
            "subgraph_001",
            2,
            root.join("source/round_2"),
        );
        let model =
            PolishPaths::at_round_dir(&root, "mito", "subgraph_001", 2, root.join("model/round_2"));
        source.input_reads = root.join("reads.fasta");
        for path in [
            &source.round1_sv_whole_read_evidence,
            &model.round1_sv_whole_read_evidence,
        ] {
            fs::create_dir_all(path.parent().unwrap()).unwrap();
        }
        let mut left = varied_dna(428, 259);
        left.push('T');
        let right = varied_dna(731, 260);
        let current = format!("{left}{right}");
        let source_alts = [
            "TATTTTGGGGGGG",
            "TATTTTGGGGGGGG",
            "TATTTTGGGGGGGGG",
            "TTATTTTGGGGGGGG",
            "TTATTTTGGGGGGGGGG",
            "TTG",
            "TTGG",
            "TTGGG",
            "TTGGGGGG",
            "TTTGGGG",
            "TTTGGGGG",
            "TTTGGGGGG",
            "TTTTGGG",
            "TTTTGGGG",
            "TTTTGGGGG",
        ];
        let candidate = Candidate {
            source_row: 1,
            source_rows: vec![1],
            pos: 260,
            reference: "T".into(),
            alleles: source_alts
                .iter()
                .map(|alt| Allele {
                    sequence: (*alt).into(),
                    support: 1,
                    entry_support: 1,
                    trial: true,
                })
                .collect(),
            depth: 347,
            total: 15,
            source_ids: None,
        };
        let chosen = 2;
        let selected = &source_alts[chosen - 1][1..];
        let model_sequence = format!("{left}{selected}{right}");
        let observed = ["TTGGGGGGGGGGGG", "TTGGGGGGGGGGGGGGGGGGGG"];
        let header = "read_id\tread_length\tquery_start\tquery_end\ttarget_start\ttarget_end\tstrand\talignment_role\tmapq\tcigar\n";
        let mut source_sv = header.to_string();
        let mut model_sv = header.to_string();
        let mut reads = String::new();
        let mut classes = "step\tread_id\texact_allele\tclass\n".to_string();
        let mut pool = BTreeMap::new();
        for i in 0..347 {
            let id = format!("r{i:03}");
            pool.insert(id.clone(), ".".into());
            let read = if i < 2 {
                let core = &observed[i][1..];
                let sequence = format!("{left}{core}{right}");
                let len = sequence.len();
                let strand = if i == 0 { "+" } else { "-" };
                let model_cigar = if core.len() == selected.len() {
                    format!("{len}M")
                } else {
                    format!(
                        "{}M{}I260M",
                        260 + selected.len(),
                        core.len() - selected.len()
                    )
                };
                source_sv.push_str(&format!(
                    "{id}\t{len}\t1\t{len}\t1\t520\t{strand}\tprimary\t60\t260M{}I260M\n",
                    core.len()
                ));
                model_sv.push_str(&format!(
                    "{id}\t{len}\t1\t{len}\t1\t{}\t{strand}\tprimary\t60\t{model_cigar}\n",
                    model_sequence.len()
                ));
                classes.push_str(&format!("1\t{id}\t{}\tALT\n", observed[i]));
                if i == 0 {
                    sequence
                } else {
                    reverse_complement(&sequence)
                }
            } else {
                classes.push_str(&format!("1\t{id}\t.\tuncertain\n"));
                current.clone()
            };
            reads.push_str(&format!(">{id}\n{read}\n"));
        }
        fs::write(&source.input_reads, &reads).unwrap();
        fs::write(&source.round1_sv_whole_read_evidence, &source_sv).unwrap();
        fs::write(&model.round1_sv_whole_read_evidence, &model_sv).unwrap();
        let class_path = root.join("classes.tsv");
        fs::write(&class_path, &classes).unwrap();
        let verify = |pool: &BTreeMap<String, String>| {
            replay_kept_short_classes(
                &source,
                &model,
                &current,
                &model_sequence,
                &candidate,
                chosen,
                pool,
                &Table::read(&class_path).unwrap(),
                1,
            )
        };
        let result = verify(&pool).unwrap();
        assert_eq!(
            (
                result.len(),
                result
                    .values()
                    .filter(|allele| allele.as_str() != ".")
                    .count()
            ),
            (347, 2)
        );
        assert_eq!(result["r000"], observed[0]);
        assert_eq!(result["r001"], observed[1]);
        assert_eq!(candidate.alleles.len(), 15); // Observed competitors are not new proposed events.
        let alts = source_alts.iter().map(|a| a.to_string()).collect();
        assert!(short_classes_need_replay(&Table::read(&class_path).unwrap(), 1, &alts).unwrap());
        for altered in [
            classes.replace(observed[0], source_alts[chosen - 1]),
            classes.replace("1\tr001\t", "1\tr999\t"),
            classes.replace("1\tr001\t", "1\tr000\t"),
        ] {
            fs::write(&class_path, altered).unwrap();
            assert!(verify(&pool).is_err());
        }
        fs::write(&class_path, &classes).unwrap();
        let mut missing = pool.clone();
        missing.remove("r346");
        assert!(verify(&missing).is_err());
        for path in [
            &source.round1_sv_whole_read_evidence,
            &model.round1_sv_whole_read_evidence,
        ] {
            let original = fs::read_to_string(path).unwrap();
            fs::write(path, original.replacen("\t60\t", "\t19\t", 1)).unwrap();
            assert!(verify(&pool).is_err());
            fs::write(path, original).unwrap();
        }
        fs::write(
            &class_path,
            classes
                .replace(&format!("\t{}\t", observed[0]), &format!("\t{}\t", source_alts[0]))
                .replace(&format!("\t{}\t", observed[1]), &format!("\t{}\t", source_alts[1])),
        )
        .unwrap();
        assert!(!short_classes_need_replay(&Table::read(&class_path).unwrap(), 1, &alts).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn short_insertion_types_target_and_complete_other_alleles() {
        let selected = "TTTCAAACCATAAAAA";
        for observed in [selected, "TTTCAAACCATAAAAAA", "TTTCAAACCATAAAAAAAAAAAAAAA"] {
            let (read, source, alternate) = short_profile_pair(observed, selected);
            assert_eq!(short_insertion_allele(&read, &source, &alternate, 260, selected), Some(observed.into()));
        }
        let other_same_length = "TTTCAAACCATAAAAT";
        let (read, source, alternate) = short_profile_pair(other_same_length, selected);
        assert_eq!(short_insertion_allele(&read, &source, &alternate, 260, selected), Some(other_same_length.into()));
        let mut partially_mapped_other = alternate.clone();
        partially_mapped_other.inside_mapped = selected.len() - 1;
        assert_eq!(short_insertion_allele(&read, &source, &partially_mapped_other, 260, selected), Some(other_same_length.into()));
    }

    #[test]
    fn short_insertion_ignores_separate_nearby_one_base_event() {
        let selected = "TTTCAAACCATAAAAA";
        let site = 260usize;
        let source = format!("{}{}", "A".repeat(site), "C".repeat(site));
        let alternate = format!("{}{}{}", "A".repeat(site), selected, "C".repeat(site));
        let read = format!("{}{}{}G{}", "A".repeat(site), selected, "C".repeat(9), "C".repeat(251));
        let len = read.len().to_string();
        let source_end = source.len().to_string();
        let alternate_end = alternate.len().to_string();
        let source_fields = ["r1", &len, "1", &len, "1", &source_end, "+", "primary", "60", "260M16I9M1I251M"];
        let alternate_fields = ["r1", &len, "1", &len, "1", &alternate_end, "+", "primary", "60", "285M1I251M"];
        let columns = ShortInsertionColumns {
            read_id: 0, read_length: 1, query_start: 2, query_end: 3,
            target_start: 4, target_end: 5, strand: 6, role: 7, mapq: 8, cigar: 9,
        };
        let left = short_insertion_profile(&source_fields, columns, &read, &source, site, 0, 60).unwrap();
        let right = short_insertion_profile(&alternate_fields, columns, &read, &alternate, site, selected.len(), 60).unwrap();
        assert_eq!(left.insertions.len(), 1);
        assert_eq!(short_insertion_allele(&read, &left, &right, site, selected), Some(selected.into()));

        let long_read = format!("{}{}{}{}{}", "A".repeat(site), selected, "C".repeat(9), "G".repeat(12), "C".repeat(251));
        let long_len = long_read.len().to_string();
        let long_source_fields = ["r2", &long_len, "1", &long_len, "1", &source_end, "+", "primary", "60", "260M16I9M12I251M"];
        let long_alternate_fields = ["r2", &long_len, "1", &long_len, "1", &alternate_end, "+", "primary", "60", "285M12I251M"];
        let long_left = short_insertion_profile(&long_source_fields, columns, &long_read, &source, site, 0, 60).unwrap();
        let long_right = short_insertion_profile(&long_alternate_fields, columns, &long_read, &alternate, site, selected.len(), 60).unwrap();
        assert!(long_left.nearby_long_event && long_right.nearby_long_event);
        assert_eq!(short_insertion_allele(&long_read, &long_left, &long_right, site, selected), None);

        let deletion_read = format!("{}{}{}{}", "A".repeat(site), selected, "C".repeat(9), "C".repeat(238));
        let deletion_len = deletion_read.len().to_string();
        let deletion_source_fields = ["r3", &deletion_len, "1", &deletion_len, "1", &source_end, "+", "primary", "60", "260M16I9M13D238M"];
        let deletion_alternate_fields = ["r3", &deletion_len, "1", &deletion_len, "1", &alternate_end, "+", "primary", "60", "285M13D238M"];
        let deletion_left = short_insertion_profile(&deletion_source_fields, columns, &deletion_read, &source, site, 0, 60).unwrap();
        let deletion_right = short_insertion_profile(&deletion_alternate_fields, columns, &deletion_read, &alternate, site, selected.len(), 60).unwrap();
        assert!(deletion_left.nearby_long_event && deletion_right.nearby_long_event);
        assert_eq!(short_insertion_allele(&deletion_read, &deletion_left, &deletion_right, site, selected), None);
    }

    #[test]
    fn short_insertion_rejects_conflicts_shifted_windows_and_multiple_primaries() {
        let selected = "TTTCAAACCATAAAAA";
        let observed = "TTTCAAACCATAAAAAA";
        let (read, source, alternate) = short_profile_pair(observed, selected);
        let mut wrong_bases = source.clone();
        wrong_bases.insertions[0].1 = selected.into();
        assert_eq!(short_insertion_allele(&read, &wrong_bases, &alternate, 260, selected), None);
        let (target_read, target_source, mut target_alternate) = short_profile_pair(selected, selected);
        target_alternate.inside_mapped = selected.len() - 1;
        assert_eq!(short_insertion_allele(&target_read, &target_source, &target_alternate, 260, selected), None);
        let mut shifted = alternate.clone();
        shifted.right_query += 1;
        assert_eq!(short_insertion_allele(&read, &source, &shifted, 260, selected), None);
        let mut reverse = alternate.clone();
        reverse.strand = '-';
        assert_eq!(short_insertion_allele(&read, &source, &reverse, 260, selected), None);
        let mut nearby_long = source.clone();
        nearby_long.nearby_long_event = true;
        assert_eq!(short_insertion_allele(&read, &nearby_long, &alternate, 260, selected), None);
        let mut same_anchor_twice = source.clone();
        same_anchor_twice.insertions.push((260, "A".repeat(12)));
        assert_eq!(short_insertion_allele(&read, &same_anchor_twice, &alternate, 260, selected), None);
        assert_eq!(short_insertion_call(&read, &[Some(source.clone()), Some(source)], &[Some(alternate)], 260, selected), None);
    }

    fn varied_dna(mut state: u64, length: usize) -> String {
        (0..length)
            .map(|_| {
                state ^= state << 13;
                state ^= state >> 7;
                state ^= state << 17;
                [b'A', b'C', b'G', b'T'][(state & 3) as usize] as char
            })
            .collect()
    }

    #[test]
    fn public_long_event_family_check_uses_the_frozen_rule() {
        let seed=varied_dna(19,520);let mut family=seed.clone().into_bytes();
        family[260]=if family[260]==b'A' {b'C'} else {b'A'};
        let family=String::from_utf8(family).unwrap();
        assert!(super::super::same_long_indel_event("G", &format!("G{seed}"), &format!("G{family}")));
        assert!(!super::super::same_long_indel_event("G", &format!("G{seed}"), &format!("G{}",varied_dna(98,520))));
        assert!(!super::super::same_long_indel_event("G", "GACGT", "GACGT"));
        assert!(!super::super::same_long_indel_event("G", &format!("G{seed}"), "G"));
    }

