    #[test]
    fn nested_repeat_uses_its_internal_model_round_without_relaxing_public_anchor() {
        let fixture = NestedFixture::new();
        let (_, config) = parse_args(&[
            "--homorepair-source-dir".into(),
            fixture.source.round_dir.display().to_string(),
        ])
        .unwrap();
        assert!(super::super::run_review(&fixture.options, &config.unwrap())
            .err()
            .unwrap()
            .to_string()
            .contains("output is anchored to source_dir"));
        let before = fs::read(fixture.source.validation_fasta()).unwrap();
        let modified = fs::metadata(fixture.source.validation_fasta())
            .unwrap()
            .modified()
            .unwrap();
        let result = nested_repeat(&fixture.options, &fixture.source, &fixture.fasta, 0.2).unwrap();
        assert_eq!(result.sequence, "ACGTACGT");
        assert_eq!(result.edit_count, 0);
        assert_eq!(result.frame.round_dir, fixture.source.round_dir);
        let report = fixture.source.subgraph_dir.join("round_hr/logs/run.tsv");
        assert_eq!(
            report_value(&report, "outcome", "homorepair", "status").unwrap(),
            "complete"
        );
        assert_eq!(
            report_value(&report, "outcome", "homorepair", "unresolved_count").unwrap(),
            "0"
        );
        assert_eq!(fs::read(fixture.source.validation_fasta()).unwrap(), before);
        assert_eq!(
            fs::metadata(fixture.source.validation_fasta())
                .unwrap()
                .modified()
                .unwrap(),
            modified
        );
        assert!(!fixture.source.subgraph_dir.join("round_3").exists());
        let outer = fixture.options.out_dir.join("mito/component");
        assert!(!outer.join("round_2").exists());
        assert!(!outer.join("round_3").exists());
        assert!(!outer.join("round_hr/logs").exists());
    }

