    fn mixed_long_event_source(
        short_support: usize,
        seed_support: usize,
        family_support: usize,
        depth: usize,
    ) -> (String, Table) {
        let reference = format!("{}G{}", varied_dna(17, 120), varied_dna(49, 120));
        let seed = varied_dna(13, 520);
        let mut family = seed.as_bytes().to_vec();
        family[260] = if family[260] == b'A' { b'C' } else { b'A' };
        let family = String::from_utf8(family).unwrap();
        assert!(compatible_long_event(&seed, &family));
        let rows = [
            (format!("G{seed}"), seed_support),
            (format!("G{family}"), family_support),
            ("GT".into(), short_support),
            ("GTC".into(), 1),
        ]
        .into_iter()
        .enumerate()
        .map(|(i, (alt, support))| {
            assert!(!is_repeat(&reference, 121, "G", &alt));
            vec![
                "121".into(),
                "G".into(),
                alt,
                support.to_string(),
                depth.to_string(),
                (0..support)
                    .map(|n| format!("a{i}_{n}"))
                    .collect::<Vec<_>>()
                    .join(","),
            ]
        })
        .collect();
        (
            reference,
            Table {
                header: ["pos", "ref", "alt", "counts", "depth", "read_ids"]
                    .iter()
                    .map(|s| (*s).into())
                    .collect(),
                rows,
                row_numbers: vec![1, 2, 3, 4],
            },
        )
    }

    #[test]
    fn long_event_entry_is_not_blocked_by_group_screened_low_support_short_trials() {
        let (reference, table) = mixed_long_event_source(1, 12, 10, 100);
        let found = candidates(&reference, &table, &SOURCE_SCREEN).unwrap();
        assert_eq!(found.len(), 1);
        let candidate = &found[0];
        assert_eq!(
            (
                candidate.alleles[0].support,
                candidate.alleles[0].entry_support
            ),
            (12, 22)
        );
        assert!(candidate.alleles[0].trial);
        assert!(!candidate.alleles[1].trial);
        assert!(candidate.alleles[2..]
            .iter()
            .all(|allele| allele.trial && allele.support == 1));
        assert_eq!(ranked_trials(candidate), vec![1, 3, 4]);
        assert_eq!(
            planned_probe_count(ranked_trials(candidate).len(), 0),
            Some(1)
        );
        // Every original ALT read remains available to the fixed-pool caller.
        assert_eq!(
            candidate
                .source_ids
                .as_ref()
                .unwrap()
                .iter()
                .map(BTreeSet::len)
                .collect::<Vec<_>>(),
            vec![12, 10, 1, 1]
        );
        assert_eq!(candidate.total, 24);
    }

