    #[test]
    fn long_event_entry_requires_deduplicated_ids_and_consistent_depth() {
        let (reference, mut table) = mixed_long_event_source(1, 12, 10, 100);
        table.rows[1][5] = (0..10)
            .map(|n| format!("a0_{n}"))
            .collect::<Vec<_>>()
            .join(",");
        assert!(candidates(&reference, &table, &SOURCE_SCREEN)
            .unwrap()
            .is_empty());
        let (reference, mut table) = mixed_long_event_source(1, 12, 10, 100);
        table.rows[1][4] = "101".into();
        let found = candidates(&reference, &table, &SOURCE_SCREEN).unwrap();
        assert!(!found[0].alleles[0].trial);
        assert!(!found[0].alleles[1].trial);
        assert!(found[0].source_ids.is_none());
        let (reference, mut table) = mixed_long_event_source(1, 12, 10, 100);
        table.header.pop();
        for row in &mut table.rows {
            row.pop();
        }
        assert!(candidates(&reference, &table, &SOURCE_SCREEN).is_err());
    }

    #[test]
    fn long_event_entry_joins_only_sequence_compatible_source_reads() {
        let reference = format!("{}A{}", varied_dna(17, 120), varied_dna(49, 120));
        let seed = varied_dna(13, 520);
        let pos = 121;
        let mut rows = Vec::new();
        let mut row_numbers = Vec::new();
        let mut seed_ids = Vec::new();
        for i in 0..53 {
            seed_ids.push(format!("seed_{i}"));
        }
        rows.push(vec![
            pos.to_string(), "A".into(), format!("A{seed}"), "53".into(),
            "1000".into(), seed_ids.join(","),
        ]);
        row_numbers.push(1);
        for index in 0..29 {
            let mut core = seed.as_bytes().to_vec();
            let base = 45 + index * 14;
            core[base] = match core[base] { b'A' => b'C', _ => b'A' };
            rows.push(vec![
                pos.to_string(), "A".into(),
                format!("A{}", String::from_utf8(core).unwrap()),
                "15".into(), "1000".into(),
                (0..15).map(|n| format!("family_{index}_{n}")).collect::<Vec<_>>().join(","),
            ]);
            row_numbers.push(rows.len());
        }
        let unrelated = varied_dna(987, 520);
        rows.push(vec![
            pos.to_string(), "A".into(), format!("A{unrelated}"), "150".into(),
            "1000".into(), (0..150).map(|n| format!("unrelated_{n}")).collect::<Vec<_>>().join(","),
        ]);
        row_numbers.push(rows.len());
        let table = Table {
            header: ["pos", "ref", "alt", "counts", "depth", "read_ids"]
                .iter().map(|value| (*value).into()).collect(),
            rows,
            row_numbers,
        };
        let found = candidates(&reference, &table, &SOURCE_SCREEN).unwrap();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0].alleles[0].support, 53);
        assert_eq!(found[0].alleles[0].entry_support, 488);
        assert_eq!(ranked_trials(&found[0]), vec![1]);
        assert!(!found[0].alleles.last().unwrap().trial);
    }

