    #[test]
    fn full_insert_sequence_check_rejects_same_length_middle_replacement() {
        let expected = varied_dna(319, 520);
        let mut observed = expected.as_bytes().to_vec();
        for base in &mut observed[130..390] {
            *base = match *base { b'A' => b'T', b'T' => b'A', b'C' => b'G', _ => b'C' };
        }
        let wrong_middle = String::from_utf8(observed).unwrap();
        assert_eq!(expected.len(), wrong_middle.len());
        assert_eq!(&expected[..130], &wrong_middle[..130]);
        assert_eq!(&expected[390..], &wrong_middle[390..]);
        assert!(!insertion_matches_event(&wrong_middle, &expected));
        assert!(insertion_matches_event(&expected, &expected));
    }

    #[test]
    fn short_insert_sequence_check_rejects_different_alleles() {
        for length in [12, 20, 99] {
            let expected = varied_dna(length as u64 + 439, length);
            let mut different = expected.as_bytes().to_vec();
            for base in &mut different[length / 3..length * 2 / 3] {
                *base = match *base { b'A' => b'C', b'C' => b'T', b'T' => b'G', _ => b'A' };
            }
            let different = String::from_utf8(different).unwrap();
            assert_eq!(different.len(), expected.len());
            assert!(!insertion_matches_event(&different, &expected));
            assert!(insertion_matches_event(&expected, &expected));
        }
    }

    #[test]
    fn paired_cigar_event_counts_each_read_once_and_keeps_unknown_in_remainder() {
        let root = std::env::temp_dir().join(format!(
            "orgraft_event_{}_{}", std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()
        ));
        fs::create_dir_all(&root).unwrap();
        let source = root.join("source.tsv");
        let alternate = root.join("alternate.tsv");
        let header = "read_id\ttarget_start\ttarget_end\talignment_role\tmapq\tidentity\tcigar\tquery_start\tquery_end\tstrand\n";
        let mut source_text = header.to_string();
        let mut alternate_text = header.to_string();
        for id in ["long_1", "long_2", "long_3"] {
            source_text.push_str(&format!("{id}\t1\t500\tprimary\t60\t96\t200M120I300M\t1\t620\t+\n"));
            alternate_text.push_str(&format!("{id}\t1\t620\tprimary\t60\t97\t620M\t1\t620\t+\n"));
        }
        source_text.push_str("short\t1\t500\tprimary\t60\t97\t500M\t1\t500\t+\n");
        alternate_text.push_str("short\t1\t620\tprimary\t60\t96\t200M120D300M\t1\t500\t+\n");
        fs::write(&source, source_text).unwrap();
        fs::write(&alternate, alternate_text).unwrap();
        let pool = BTreeMap::from([("untyped".into(), ReadLocus::default())]);
        let insert = "ACGTGATCTAGCTAGGCTAACGTTAGCGACTACGATCGATGCTAGCACTGATCGTAGCTAGCGATCGTACGATGCTAGCTGATCGATCGTAGCTAGCTAGTACGATCGTAGCTAGCTAGA";
        let mut reads = HashMap::from([
            ("long_1".into(), format!("{}{}{}", "A".repeat(200), insert, "C".repeat(300))),
            ("long_2".into(), format!("{}{}{}", "A".repeat(200), insert, "C".repeat(300))),
            ("long_3".into(), format!("{}{}{}", "A".repeat(200), insert, "C".repeat(300))),
            ("short".into(), format!("{}{}", "A".repeat(200), "C".repeat(300))),
        ]);
        let short_reference = format!("{}{}", "A".repeat(200), "C".repeat(300));
        let long_reference = format!("{}{}{}", "A".repeat(200), insert, "C".repeat(300));
        let support = paired_event_support(&source, &alternate, 200, 120, true,
            &short_reference, &long_reference, &pool, 2, 1, &reads, insert).unwrap();
        assert_eq!((support.depth, support.counts.as_slice(), support.remainder, support.uncertain),
            (5, [1, 3].as_slice(), 2, 1));
        assert_eq!(strict_choice_from(&support, &BTreeSet::from([1])), Some(1));
        writeln!(OpenOptions::new().append(true).open(&source).unwrap(),
            "wrong\t1\t500\tprimary\t60\t96\t200M120I300M\t1\t620\t+").unwrap();
        writeln!(OpenOptions::new().append(true).open(&alternate).unwrap(),
            "wrong\t1\t620\tprimary\t60\t97\t620M\t1\t620\t+").unwrap();
        reads.insert("wrong".into(), format!("{}{}{}", "A".repeat(200), "T".repeat(120), "C".repeat(300)));
        let wrong_sequence = paired_event_support(&source, &alternate, 200, 120, true,
            &short_reference, &long_reference, &pool, 2, 1, &reads, insert).unwrap();
        assert_eq!((wrong_sequence.depth, wrong_sequence.counts.as_slice(), wrong_sequence.remainder),
            (6, [1, 3].as_slice(), 3));
        assert_eq!(strict_choice_from(&wrong_sequence, &BTreeSet::from([1])), None);
        writeln!(OpenOptions::new().append(true).open(&source).unwrap(),
            "low_mapq\t1\t500\tprimary\t10\t96\t200M120I300M\t1\t620\t+").unwrap();
        writeln!(OpenOptions::new().append(true).open(&alternate).unwrap(),
            "low_mapq\t1\t620\tprimary\t10\t97\t620M\t1\t620\t+").unwrap();
        reads.insert("low_mapq".into(), format!("{}{}{}", "A".repeat(200), insert, "C".repeat(300)));
        let low_mapq = paired_event_support(&source, &alternate, 200, 120, true,
            &short_reference, &long_reference, &pool, 2, 1, &reads, insert).unwrap();
        assert_eq!((low_mapq.depth, low_mapq.counts.as_slice(), low_mapq.remainder),
            (7, [1, 3].as_slice(), 4));
        fs::remove_file(source).unwrap();
        fs::remove_file(alternate).unwrap();
        fs::remove_dir(root).unwrap();
    }

    #[test]
    fn event_and_other_exact_alt_are_mutually_exclusive() {
        let event = Support {
            depth: 5, total: 2, main: 2, remainder: 3, uncertain: 2,
            untried_exact: 0, counts: vec![1, 2, 0],
            classes: vec![
                ("conflict".into(), Some(1)),
                ("event".into(), Some(1)),
                ("reference".into(), Some(0)),
                ("other".into(), None),
                ("event_without_CIGAR".into(), None),
            ],
        };
        let exact = Support {
            depth: 5, total: 4, main: 2, remainder: 1, uncertain: 0,
            untried_exact: 2, counts: vec![1, 2, 2],
            classes: vec![
                ("conflict".into(), Some(2)),
                ("event".into(), Some(1)),
                ("reference".into(), Some(0)),
                ("other".into(), Some(2)),
                ("event_without_CIGAR".into(), Some(1)),
            ],
        };
        let alleles = vec!["G".to_string(), format!("G{}", varied_dna(11, 520)),
            format!("G{}", varied_dna(13, 520))];
        let merged = merge_event_and_exact_classes(event, &exact, 1, &alleles);
        assert_eq!(merged.counts, vec![1, 1, 1]);
        assert_eq!((merged.depth, merged.total, merged.main, merged.remainder,
                    merged.uncertain, merged.untried_exact), (5, 2, 1, 3, 2, 1));
        assert_eq!(strict_choice_from(&merged, &BTreeSet::from([1])), None);
    }

    #[test]
    fn exact_error_allele_in_same_event_family_does_not_veto_paired_read() {
        let seed = varied_dna(19, 520);
        let mut family = seed.clone().into_bytes();
        family[260] = if family[260] == b'A' { b'C' } else { b'A' };
        let family = String::from_utf8(family).unwrap();
        let mut wrong = seed.clone().into_bytes();
        for base in &mut wrong[173..347] {
            *base = match *base { b'A' => b'C', b'C' => b'G', b'G' => b'T', _ => b'A' };
        }
        let wrong = String::from_utf8(wrong).unwrap();
        assert!(compatible_long_event(&seed, &family));
        assert!(!compatible_long_event(&seed, &wrong));
        let alleles = vec!["G".to_string(), format!("G{seed}"),
            format!("G{family}"), format!("G{wrong}")];
        let event = Support {
            depth: 6, total: 3, main: 3, remainder: 3, uncertain: 2,
            untried_exact: 0, counts: vec![1, 3, 0, 0],
            classes: vec![
                ("same_event".into(), Some(1)),
                ("wrong_middle".into(), Some(1)),
                ("exact_event".into(), Some(1)),
                ("reference".into(), Some(0)),
                ("family_without_event_evidence".into(), None),
                ("other_without_event_evidence".into(), None),
            ],
        };
        let exact = Support {
            depth: 6, total: 5, main: 2, remainder: 1, uncertain: 0,
            untried_exact: 0, counts: vec![1, 1, 2, 2],
            classes: vec![
                ("same_event".into(), Some(2)),
                ("wrong_middle".into(), Some(3)),
                ("exact_event".into(), Some(1)),
                ("reference".into(), Some(0)),
                ("family_without_event_evidence".into(), Some(2)),
                ("other_without_event_evidence".into(), Some(3)),
            ],
        };
        let merged = merge_event_and_exact_classes(event, &exact, 1, &alleles);
        assert_eq!(merged.classes.iter().map(|(_, class)| *class).collect::<Vec<_>>(),
            vec![Some(1), None, Some(1), Some(0), None, Some(3)]);
        assert_eq!((merged.depth, merged.counts, merged.remainder, merged.uncertain),
            (6, vec![1, 2, 0, 1], 3, 2));
    }

    #[test]
    fn two_nearby_insertions_cannot_be_combined_into_one_event() {
        let root = std::env::temp_dir().join(format!(
            "orgraft_split_event_{}_{}", std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()
        ));
        fs::create_dir_all(&root).unwrap();
        let source = root.join("source.tsv");
        let alternate = root.join("alternate.tsv");
        let header = "read_id\ttarget_start\ttarget_end\talignment_role\tmapq\tidentity\tcigar\tquery_start\tquery_end\tstrand\n";
        fs::write(&source, format!("{header}split\t1\t500\tprimary\t60\t96\t200M60I1M60I299M\t1\t620\t+\n")).unwrap();
        fs::write(&alternate, format!("{header}split\t1\t620\tprimary\t60\t97\t620M\t1\t620\t+\n")).unwrap();
        let insert = varied_dna(29, 120);
        let short_reference = format!("{}{}", "A".repeat(200), "C".repeat(300));
        let long_reference = format!("{}{}{}", "A".repeat(200), insert, "C".repeat(300));
        let read = format!("{}{}C{}{}", "A".repeat(200), &insert[..60], &insert[60..], "C".repeat(299));
        let reads = HashMap::from([("split".into(), read)]);
        let support = paired_event_support(&source, &alternate, 200, 120, true,
            &short_reference, &long_reference, &BTreeMap::new(), 2, 1, &reads, &insert).unwrap();
        assert_eq!((support.depth, support.counts.as_slice(), support.remainder),
            (1, [0, 0].as_slice(), 1));
        // The second insertion is 50 bp away, outside the old +/-30 bp
        // shortcut but inside the event's 100 bp evidence flank.
        fs::write(&source, format!("{header}second\t1\t500\tprimary\t60\t96\t200M120I50M30I250M\t1\t650\t+\n")).unwrap();
        fs::write(&alternate, format!("{header}second\t1\t620\tprimary\t60\t97\t370M30I250M\t1\t650\t+\n")).unwrap();
        let reads = HashMap::from([("second".into(),
            format!("{}{}{}{}{}", "A".repeat(200), insert, "C".repeat(50), "G".repeat(30), "C".repeat(250)))]);
        let separated = paired_event_support(&source, &alternate, 200, 120, true,
            &short_reference, &long_reference, &BTreeMap::new(), 2, 1, &reads, &insert).unwrap();
        assert_eq!((separated.depth, separated.counts.as_slice(), separated.remainder),
            (1, [0, 0].as_slice(), 1));
        fs::remove_file(source).unwrap();
        fs::remove_file(alternate).unwrap();
        fs::remove_dir(root).unwrap();
    }

