    #[test]
    fn equivalent_deletion_edges_use_flanks_outside_the_whole_equivalence_interval() {
        let root = std::env::temp_dir().join(format!(
            "orgraft_equivalent_del_{}_{}", std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()
        ));
        fs::create_dir_all(&root).unwrap();
        let source = root.join("source.tsv");
        let alternate = root.join("alternate.tsv");
        let header = "read_id\ttarget_start\ttarget_end\talignment_role\tmapq\tidentity\tcigar\tquery_start\tquery_end\tstrand\n";
        let segment = varied_dna(55, 100);
        let prefix = format!("{}A", varied_dna(77, 99));
        let suffix = format!("T{}", varied_dna(98, 99));
        let long_reference = format!("{prefix}{segment}CG{segment}{suffix}");
        let short_reference = format!("{prefix}{segment}{suffix}");
        let deleted = &long_reference[200..302];
        assert_eq!(equivalent_deletion_interval(&long_reference, 200, 102), Some((100, 200)));
        assert!(deletion_breakpoint_equivalent(&long_reference, 200, 100, 102));
        assert!(deletion_breakpoint_equivalent(&long_reference, 200, 200, 102));
        assert!(!deletion_breakpoint_equivalent(&long_reference, 200, 99, 102));
        assert!(!deletion_breakpoint_equivalent(&long_reference, 200, 210, 102));
        let mut long_rows = header.to_string();
        let mut short_rows = header.to_string();
        for (id, cigar) in [
            ("left_edge", "100M102D200M"),
            ("right_edge", "200M102D100M"),
            ("outside_left", "99M102D201M"),
            ("outside_right", "210M102D90M"),
        ] {
            long_rows.push_str(&format!("{id}\t1\t402\tprimary\t60\t96\t{cigar}\t1\t300\t+\n"));
            short_rows.push_str(&format!("{id}\t1\t300\tprimary\t60\t97\t300M\t1\t300\t+\n"));
        }
        fs::write(&source, long_rows).unwrap();
        fs::write(&alternate, short_rows).unwrap();
        let support = paired_event_support(&source, &alternate, 200, 102, false,
            &short_reference, &long_reference, &BTreeMap::new(), 2, 1,
            &HashMap::new(), deleted).unwrap();
        assert_eq!((support.depth, support.counts.as_slice(), support.remainder),
            (4, [0, 2].as_slice(), 2));
        fs::remove_file(source).unwrap();
        fs::remove_file(alternate).unwrap();
        fs::remove_dir(root).unwrap();
    }

    #[test]
    fn legacy_exact_alt_counts_are_preserved_before_event_level_review() {
        let classes = (0..100)
            .map(|n| (format!("r{n}"), Some(if n < 30 { 0 } else if n < 70 { 1 } else { 2 })))
            .collect::<Vec<_>>();
        let initial = Support {
            depth: 100, total: 70, main: 40, remainder: 30, uncertain: 0,
            untried_exact: 30, counts: vec![30, 40, 30], classes,
        };
        assert_eq!(strict_choice_from(&initial, &BTreeSet::from([1])), Some(1));
        // Preserve the old exact-template result. This regression test does
        // not certify that every historical other-ALT read is trustworthy.
        assert_eq!((initial.total, initial.main, initial.remainder), (70, 40, 30));
        assert_eq!(strict_choice_from(&initial, &BTreeSet::from([1])), Some(1));
    }

    fn test_candidate(reference: &str, alts: &[(&str, usize)]) -> Candidate {
        Candidate {
            source_row: 1,
            source_rows: vec![1],
            pos: 2,
            reference: reference.into(),
            alleles: alts
                .iter()
                .map(|(sequence, support)| Allele {
                    sequence: (*sequence).into(),
                    support: *support,
                    entry_support: *support,
                    trial: true,
                })
                .collect(),
            depth: 100,
            total: alts.iter().map(|(_, n)| *n).sum(),
            source_ids: None,
        }
    }

    fn gate_table(rows: &[(&str, &str, &str, &str, &str, &str)]) -> Table {
        Table {
            header: ["pos", "ref", "alt", "type", "counts", "depth"]
                .iter()
                .map(|field| (*field).into())
                .collect(),
            rows: rows
                .iter()
                .map(|row| {
                    [row.0, row.1, row.2, row.3, row.4, row.5]
                        .iter()
                        .map(|field| (*field).into())
                        .collect()
                })
                .collect(),
            row_numbers: (1..=rows.len()).collect(),
        }
    }

    #[test]
    fn temporary_insertion_repeat_gate_requires_local_type_and_old_entry() {
        let temporary = format!("{}ATGCTTTTT{}", "C".repeat(61), "G".repeat(61));
        let mut candidate = test_candidate("ATGC", &[("ATGCTTTTT", 8)]);
        candidate.pos = 62;
        let selected = &candidate.alleles[0];
        let local = gate_table(&[("65", "CTTTTT", "CTTTT", "InDel,homopolymer", "3", "10")]);
        let gate = repeat_gate(&temporary, &candidate, selected, &local, &SOURCE_SCREEN).unwrap();
        assert!(gate.passed);
        assert_eq!((gate.target.start + 1, gate.target.end), (62, 70));
        assert_eq!(gate.reason, "corresponding_repeat_passed_old_entry");
        assert!(gate.local_rows[0].contains("InDel,homopolymer"));
        let record_path = std::env::temp_dir().join(format!(
            "orgraft_repeat_gate_{}_{}.tsv",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        write_repeat_gate(&record_path, 1, &candidate, selected, &gate).unwrap();
        let recorded = Table::read(&record_path).unwrap();
        assert_eq!(
            recorded.field(&recorded.rows[0], "source_type").unwrap(),
            "nonrepeat_InDel"
        );
        assert_eq!(
            recorded
                .field(&recorded.rows[0], "temporary_target_start")
                .unwrap(),
            "62"
        );
        assert_eq!(
            recorded
                .field(&recorded.rows[0], "temporary_target_end")
                .unwrap(),
            "70"
        );
        assert!(recorded
            .field(&recorded.rows[0], "local_new_table_rows_and_types")
            .unwrap()
            .contains("InDel,homopolymer"));
        assert_eq!(recorded.field(&recorded.rows[0], "gate").unwrap(), "pass");
        let low = gate_table(&[("65", "CTTTTT", "CTTTT", "InDel,homopolymer", "2", "10")]);
        let low_gate = repeat_gate(&temporary, &candidate, selected, &low, &SOURCE_SCREEN).unwrap();
        assert!(!low_gate.passed);
        assert_eq!(low_gate.reason, "corresponding_repeat_below_old_entry");
        write_repeat_gate(&record_path, 2, &candidate, selected, &low_gate).unwrap();
        let recorded = Table::read(&record_path).unwrap();
        assert_eq!(recorded.field(&recorded.rows[1], "gate").unwrap(), "skip");
        assert_eq!(
            recorded.field(&recorded.rows[1], "reason").unwrap(),
            "corresponding_repeat_below_old_entry"
        );
        std::fs::remove_file(record_path).unwrap();
        let nonrepeat = gate_table(&[("65", "CTTTTT", "CATTTTT", "InDel,other", "3", "10")]);
        assert_eq!(
            repeat_gate(&temporary, &candidate, selected, &nonrepeat, &SOURCE_SCREEN)
                .unwrap()
                .reason,
            "corresponding_residual_remains_nonrepeat"
        );
    }

    #[test]
    fn repeat_elsewhere_does_not_open_the_local_gate() {
        let temporary = format!("{}ATGCTTTTT{}", "C".repeat(61), "G".repeat(61));
        let mut candidate = test_candidate("ATGC", &[("ATGCTTTTT", 8)]);
        candidate.pos = 62;
        // The G tract begins at the first base strictly after the temporary
        // ALT; the new table row is a real repeat, but not this site's repeat.
        let distant = gate_table(&[("71", "GGGGG", "GGGG", "InDel,homopolymer", "3", "10")]);
        let gate = repeat_gate(
            &temporary,
            &candidate,
            &candidate.alleles[0],
            &distant,
            &SOURCE_SCREEN,
        )
        .unwrap();
        assert!(!gate.passed);
        assert!(gate.local_rows.is_empty());
        assert_eq!(
            gate.reason,
            "no_corresponding_residual_after_temporary_reference"
        );
    }

    #[test]
    fn deletion_gate_uses_remaining_alt_interval_not_deleted_reference_span() {
        let mut candidate = test_candidate("ATGCTTTTT", &[("ATGC", 8)]);
        candidate.pos = 62;
        let temporary = format!("{}ATGC{}", "C".repeat(61), "G".repeat(61));
        let right_junction = gate_table(&[("65", "CGGGG", "CGGG", "InDel,homopolymer", "3", "10")]);
        let gate = repeat_gate(
            &temporary,
            &candidate,
            &candidate.alleles[0],
            &right_junction,
            &SOURCE_SCREEN,
        )
        .unwrap();
        assert_eq!((gate.target.start + 1, gate.target.end), (62, 65));
        assert!(!gate.passed);
        assert_eq!(
            gate.reason,
            "no_corresponding_residual_after_temporary_reference"
        );

        candidate.alleles[0].sequence = "ATGCTT".into();
        let temporary = format!("{}ATGCTT{}", "C".repeat(61), "G".repeat(61));
        let local = gate_table(&[("65", "CTT", "CT", "InDel,homopolymer", "3", "10")]);
        let gate = repeat_gate(
            &temporary,
            &candidate,
            &candidate.alleles[0],
            &local,
            &SOURCE_SCREEN,
        )
        .unwrap();
        assert_eq!((gate.target.start + 1, gate.target.end), (62, 67));
        assert!(gate.passed);
    }

    #[test]
    fn short_and_long_nonrepeat_indels_have_no_length_cutoff() {
        let reference = format!("{}ATGC{}", "C".repeat(61), "G".repeat(61));
        let pos = 62;
        assert!(!is_repeat(&reference, pos, "ATGC", "ATGCA"));
        assert!(!is_repeat(
            &reference,
            pos,
            "ATGC",
            &format!("ATGC{}", "TACG".repeat(20))
        ));
        assert_eq!(
            replace(&reference, pos, "ATGC", "ATGCA").unwrap().len(),
            reference.len() + 1
        );
        assert_eq!(
            replace(
                &reference,
                pos,
                "ATGC",
                &format!("ATGC{}", "TACG".repeat(20))
            )
            .unwrap()
            .len(),
            reference.len() + 80
        );
    }

    #[test]
    fn fixed_pool_keeps_unclassified_reads_in_remainder_and_requires_unique_alt() {
        let candidate = test_candidate("AT", &[("A", 7), ("ATG", 4)]);
        let mut pool = BTreeMap::new();
        let mut reads = HashMap::new();
        for i in 0..10 {
            let id = format!("r{i}");
            let read = if i < 6 {
                "CCAGG"
            } else if i == 6 {
                "CCATCGG"
            } else {
                "NNN"
            };
            pool.insert(
                id.clone(),
                ReadLocus {
                    windows: BTreeSet::from([ReadWindow {
                        start: 0,
                        end: read.len(),
                        strand: '+',
                    }]),
                    ambiguous: false,
                    model_windows: BTreeMap::new(),
                },
            );
            reads.insert(id, read.into());
        }
        let support = classify(
            &pool,
            &reads,
            &["CCATGG".into(), "CCAGG".into(), "CCATCGG".into()],
            &[true, true, true],
        );
        assert_eq!(
            (
                support.depth,
                support.total,
                support.main,
                support.remainder,
                support.uncertain
            ),
            (10, 7, 6, 3, 3)
        );
        assert_eq!(strict_choice(&candidate, &support), Some(1));
        let tied = Support {
            counts: vec![0, 4, 4],
            depth: 10,
            total: 8,
            main: 4,
            remainder: 2,
            uncertain: 2,
            untried_exact: 0,
            classes: Vec::new(),
        };
        assert_eq!(strict_choice(&candidate, &tied), None);
    }

    #[test]
    fn later_planned_model_reads_can_reverse_an_early_strict_choice() {
        let candidate = test_candidate("AT", &[("A", 7)]);
        let mut pool = BTreeMap::new();
        let mut reads = HashMap::new();
        for i in 0..10 {
            let id = format!("r{i}");
            let read = if i < 6 { "CCAGG" } else { "NNNNN" };
            pool.insert(
                id.clone(),
                ReadLocus {
                    windows: BTreeSet::from([ReadWindow {
                        start: 0,
                        end: read.len(),
                        strand: '+',
                    }]),
                    ambiguous: false,
                    model_windows: BTreeMap::new(),
                },
            );
            reads.insert(id, read.into());
        }
        let templates = ["CCATGG".into(), "CCAGG".into()];
        let early = classify(&pool, &reads, &templates, &[true, true]);
        assert_eq!(strict_choice(&candidate, &early), Some(1));
        add_locus_reads(
            &mut pool,
            (10..15)
                .map(|i| (format!("r{i}"), ReadLocus::default()))
                .collect(),
            1,
        );
        let complete = classify(&pool, &reads, &templates, &[true, true]);
        assert_eq!(complete.depth, 15);
        assert_eq!(complete.remainder, 9);
        assert_eq!(strict_choice(&candidate, &complete), None);
    }

