    #[test]
    fn cigar_projection_handles_both_strands_and_long_indels() {
        let inserted = projected_window(0, 40, 0, 45, 45, '+', "20M5I20M", 10, 30).unwrap();
        assert_eq!((inserted.start, inserted.end), (10, 35));
        let deleted = projected_window(0, 45, 0, 40, 40, '+', "20M5D20M", 10, 35).unwrap();
        assert_eq!((deleted.start, deleted.end), (10, 30));
        let oriented = format!("{}{}{}", "A".repeat(20), "C".repeat(5), "G".repeat(20));
        let raw = format!(
            "{}{}{}",
            "N".repeat(5),
            reverse_complement(&oriented),
            "N".repeat(10)
        );
        let reverse = projected_window(0, 40, 5, 50, 60, '-', "20M5I20M", 10, 30).unwrap();
        assert_eq!((reverse.start, reverse.end), (15, 40));
        assert_eq!(
            oriented_slice(&raw, &reverse).as_deref(),
            Some(&oriented[10..35])
        );
    }

