    #[test]
    fn b2s108_shape_enters_on_over_a_thousand_same_anchor_nonrepeat_rows_only() {
        let reference = format!("{}ATGC{}", "C".repeat(61), "G".repeat(61));
        let first = "ATGCTACG";
        let second = "ATGCGATC";
        let repeat = "ATGCCCCC";
        assert!(!is_repeat(&reference, 62, "ATGC", first));
        assert!(!is_repeat(&reference, 62, "ATGC", second));
        assert!(is_repeat(&reference, 62, "ATGC", repeat));
        let mut rows = (0..1047)
            .map(|i| {
                vec![
                    "62".into(), "ATGC".into(),
                    if i < 1001 { first.into() } else { second.into() },
                    "1".into(), "2000".into(), format!("read_{i}"),
                ]
            })
            .collect::<Vec<Vec<String>>>();
        let repeat_ids = (0..500).map(|i| format!("repeat_{i}")).collect::<Vec<_>>().join(",");
        let repeat_row = vec!["62".into(), "ATGC".into(), repeat.into(), "500".into(), "2000".into(), repeat_ids];
        rows.push(repeat_row.clone());
        let table = Table {
            header: ["pos", "ref", "alt", "counts", "depth", "read_ids"].iter().map(|s| (*s).into()).collect(),
            row_numbers: (1..=rows.len()).collect(),
            rows,
        };
        let found = candidates(&reference, &table, &SOURCE_SCREEN).unwrap();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0].source_rows.len(), 1048);
        assert_eq!(found[0].alleles.iter().filter(|allele| allele.trial).count(), 2);
        assert_eq!(found[0].alleles[0].support, 1001);
        assert_eq!(ranked_trials(&found[0]), vec![1, 2]);
        assert_eq!(found[0].total, 1547);
        let below = Table {
            rows: table.rows.iter().take(300).cloned().chain(std::iter::once(repeat_row)).collect(),
            row_numbers: (1..=301).collect(),
            ..table
        };
        // Repeat reads cannot lift a 300/2000 nonrepeat family past the 20% entrance.
        assert!(candidates(&reference, &below, &SOURCE_SCREEN).unwrap().is_empty());
    }

