    #[test]
    fn ordinary_continuation_rejects_uncovered_or_changed_native_evidence() {
        for fault in 0..11 {
            let f = ContinuationFixture::new();
            match fault {
                0 => {
                    let p = f
                        .component
                        .join("round_hr_2/03.validate/01.data/candidates.tsv");
                    let text = fs::read_to_string(&p).unwrap();
                    fs::write(p, text.lines().next().unwrap().to_string() + "\n").unwrap();
                }
                1 => {
                    let p = f.component.join("round_hr/logs/run.tsv");
                    let text = fs::read_to_string(&p)
                        .unwrap()
                        .replace("indel_review_count\t0", "indel_review_count\t1");
                    fs::write(p, text).unwrap();
                }
                2 => {
                    let p = f
                        .component
                        .join("round_hr/03.validate/01.data/repeat_extra/candidates.tsv");
                    let text = fs::read_to_string(&p).unwrap().replace(
                        "source_context_not_unique_on_selected",
                        "strict_fixed_pool_failed",
                    );
                    fs::write(p, text).unwrap();
                }
                3 => {
                    let p = f
                        .component
                        .join("round_2/01.inputs/linear_subgraph.round_2.fasta");
                    fs::write(p, format!(">other_component\n{}\n", f.intermediate)).unwrap();
                }
                4 => {
                    let p = f
                        .component
                        .join("round_2/01.inputs/rotated_reference.fasta");
                    fs::write(p, ">subgraph_001\nACGT\n").unwrap();
                }
                5 => {
                    let p = f
                        .component
                        .join("round_2/01.inputs/subgraph_reads.fastq.gz");
                    fs::remove_file(&p).unwrap();
                    fs::write(p, "@other\nACGT\n+\nIIII\n").unwrap();
                }
                6 => {
                    let p = ordinary_source_paths(&f.component, &f.component.join("round_2"))
                        .unwrap()
                        .round1_sv_support_summary;
                    fs::write(p, "metric\tvalue\nstatus\tfail\n").unwrap();
                }
                7 => {
                    let p = f.component.join("round_hr/logs/run.tsv");
                    let text = fs::read_to_string(&p)
                        .unwrap()
                        .replace("adopted_edit_count\t1", "adopted_edit_count\t2");
                    fs::write(p, text).unwrap();
                }
                8 => {
                    let p = f.component.join("round_hr_2/logs/run.tsv");
                    let text = fs::read_to_string(&p)
                        .unwrap()
                        .replace("circle_end_review_count\t0", "circle_end_review_count\t1");
                    fs::write(p, text).unwrap();
                }
                9 => {
                    let p = ordinary_source_paths(&f.component, &f.component.join("round_2"))
                        .unwrap()
                        .round1_snv_indel_variant_type_annotations_combined;
                    let native = table(&[(
                        "40",
                        &format!("T{}", "C".repeat(20)),
                        &format!("T{}", "C".repeat(19)),
                        "1",
                        "100",
                    )]);
                    fs::write(
                        p,
                        format!(
                            "{}\n{}\n",
                            native.header.join("\t"),
                            native.rows[0].join("\t")
                        ),
                    )
                    .unwrap();
                }
                _ => {
                    let p = f.component.join("round_2/logs/report.tsv");
                    let text = fs::read_to_string(&p)
                        .unwrap()
                        .replace("organelle\tplastid", "organelle\tmito");
                    fs::write(p, text).unwrap();
                }
            }
            assert!(
                verify_ordinary_chain(&f.component, &f.source, 0.2, 2, 3).is_err(),
                "fault {fault}"
            );
        }
    }

