        let changes = dir.join("changes.tsv");
        let (sequence, count) = apply_selected("CAAG", &reviews, &changes).unwrap();
        assert_eq!((sequence.as_str(), count), ("CG", 1));
        let changes = Table::read(&changes).unwrap();
        assert_eq!(changes.field(&changes.rows[0], "ref").unwrap(), "CAA");
        assert_eq!(changes.field(&changes.rows[0], "alt").unwrap(), "C");
        assert!(changes
            .field(&changes.rows[0], "reason")
            .unwrap()
            .contains("uncertain_reads_removed"));
        let (review, summary) = local_case(2, 1, &[(1, 8), (2, 8)], 7);
