        apply_local_summaries(&mut reviews, &[summary]).unwrap();
        assert_eq!(
            apply_selected("CAAG", &reviews, &dir.join("unchanged.tsv")).unwrap(),
            ("CAAG".into(), 0)
        );
        let review_path = dir.join("review.tsv");
