    #[test]
    fn ties_zero_depth_excess_counts_and_malformed_evidence_do_not_confirm() {
        assert_eq!(
            decision(&table(&[("1", "CAAA", "CAAAA#CAA", "40#40", "100")])).unwrap_err(),
            "tied_main_ALT"
        );
        assert_eq!(
            decision(&table(&[("1", "CAAA", "CAAAA", "3", "0")])).unwrap_err(),
            "zero_depth"
        );
        assert_eq!(
            decision(&table(&[("1", "CAAA", "CAAAA", "11", "10")])).unwrap_err(),
            "total_ALT_exceeds_depth"
        );
        let base = table(&[("1", "CAAA", "CAAAA#CAA", "6#2", "10")]);
        for (column, value, expected) in [
            ("counts", "6", "ALT_count_mismatch"),
            ("counts", "bad#2", "malformed_ALT_counts"),
            ("depth", "bad", "invalid_depth"),
            ("total_count", "7", "total_count_mismatch"),
        ] {
            let mut t = Table {
                header: base.header.clone(),
                rows: base.rows.clone(),
                row_numbers: vec![1],
            };
            let index = t.header.iter().position(|h| h == column).unwrap();
            t.rows[0][index] = value.into();
            assert_eq!(decision(&t).unwrap_err(), expected);
        }
    }
    #[test]
    fn support_uses_native_counts_without_read_id_group_requirements() {
        let base = table(&[("1", "CAAA", "CAAAA#CAA", "6#2", "10")]);
        let read_ids = base.header.iter().position(|h| h == "read_ids").unwrap();
        for value in [
            ".",
            "read_1#read_2,read_3",
            "read_1,read_2,read_3,read_4,read_5,read_6#read_1,read_8",
            "read_1,read_1,read_3,read_4,read_5,read_6#read_7,read_8",
        ] {
            let mut t = Table {
                header: base.header.clone(),
                rows: base.rows.clone(),
                row_numbers: vec![1],
            };
            t.rows[0][read_ids] = value.into();
            assert_eq!(decision(&t).unwrap(), 0);
        }
        let mut absent = base;
        absent.header.remove(read_ids);
        absent.rows[0].remove(read_ids);
        assert_eq!(decision(&absent).unwrap(), 0);
    }
    fn initial_reviews_linear_reference(
        reference: &str,
        table: &Table,
        screen: &SourceScreen,
    ) -> Result<Vec<Review>, OrgraftError> {
        let mut reviews: Vec<Review> = Vec::new();
        for (i, row) in table.rows.iter().enumerate() {
            let passes_screen = screen.should_review(table, row)?;
            let site = source_site(reference, table, row)?;
            let too_few_copies = site.as_ref().is_some_and(|s| s.copies() < 2);
            // Low-frequency long tracts use a separate fixed-pool supplement.
            // They must not be accepted from the ordinary caller's segment subset.
            let eligible = passes_screen && !too_few_copies;
            let pending_reason = "pending_probe";
            if let Some(existing) = reviews
                .iter_mut()
                .find(|r| site.is_some() && r.site == site)
            {
                existing.source_rows.push(table.row_numbers[i]);
                if eligible && !existing.eligible {
                    existing.eligible = true;
                    existing.status = "review_required";
                    existing.reason = pending_reason.into();
                } else if passes_screen && existing.eligible {
                    // The ordinary repeat entry owns this tract. Do not append a
                    // second supplemental review, even if another row is low frequency.
                    existing.reason = "pending_probe".into();
                }
                continue;
            }
            let blocked = eligible && site.is_none();
            reviews.push(Review {
                source_rows: vec![table.row_numbers[i]],
                site,
                eligible,
                blocked,
                selected: None,
                status: if eligible {
                    "review_required"
                } else {
                    "screened_out"
                },
                reason: if too_few_copies {
                    "fewer_than_two_reference_copies"
                } else if !eligible {
                    "screened_low_source_support"
                } else if blocked {
                    "repeat_tract_not_resolved"
                } else {
                    pending_reason
                }
                .into(),
                evidence: Evidence::default(),
                local: None,
            });
        }
        // Include the preceding anchor because adopted edits use anchored alleles
        // in original-reference coordinates.
        let mut conflicts = HashSet::new();
        for (i, a) in reviews.iter().enumerate().filter(|(_, r)| r.eligible) {
            let Some(a) = &a.site else { continue };
            for (j, b) in reviews
                .iter()
                .enumerate()
                .skip(i + 1)
                .filter(|(_, r)| r.eligible)
            {
                let Some(b) = &b.site else { continue };
                if a.start.saturating_sub(1) < b.end && b.start.saturating_sub(1) < a.end {
                    conflicts.insert(i);
                    conflicts.insert(j);
                }
            }
        }
        for i in conflicts {
            reviews[i].blocked = true;
            reviews[i].reason = "overlapping_repeat_candidates".into();
        }
        Ok(reviews)
    }

    #[test]
    fn indexed_review_dedup_preserves_linear_results_with_late_eligible_rows() {
        // Native reports can contain several differently anchored rows for one
        // tract. A later high-support row must promote its existing review.
        let mut reference = String::new();
        let mut specs = Vec::<(String, String, String, String, String)>::new();
        for _ in 0..64 {
            let start = reference.len();
            reference.push_str("CAAAAGTTTTGC");
            specs.push((
                (start + 1).to_string(),
                "CAAAA".into(),
                "CAAA".into(),
                "1".into(),
                "100".into(),
            ));
            specs.push((
                (start + 6).to_string(),
                "GTTTT".into(),
                "GTTT".into(),
                "25".into(),
                "100".into(),
            ));
        }
        // Opposite order deliberately exercises lookup independent of the
        // order in which tracts first appeared in the original report.
        for i in (0..64).rev() {
            specs.push((
                (i * 12 + 2).to_string(),
                "AAAA".into(),
                "AAA".into(),
                "30".into(),
                "100".into(),
            ));
            specs.push((
                (i * 12 + 6).to_string(),
                "GTTTT".into(),
                "GTTT".into(),
                "1".into(),
                "100".into(),
            ));
        }
        // Unresolved annotations must remain separate rows, just as before.
        specs.extend([
            (
                "1".into(),
                "C".into(),
                "G".into(),
                "30".into(),
                "100".into(),
            ),
            ("1".into(), "C".into(), "G".into(), "1".into(), "100".into()),
        ]);
        let borrowed = specs
            .iter()
            .map(|(p, r, a, c, d)| (p.as_str(), r.as_str(), a.as_str(), c.as_str(), d.as_str()))
            .collect::<Vec<_>>();
        let mut table = table(&borrowed);
        table.row_numbers = (0..table.rows.len()).map(|i| i * 3 + 7).collect();
        let expected = initial_reviews_linear_reference(&reference, &table, &SOURCE_SCREEN).unwrap();
        let actual = initial_reviews(&reference, &table, &SOURCE_SCREEN).unwrap();
        assert_eq!(format!("{actual:?}"), format!("{expected:?}"));
        assert_eq!(actual.len(), 130);
        assert_eq!(actual[0].site.as_ref().unwrap().start, 1);
        assert_eq!(actual[1].site.as_ref().unwrap().start, 6);
        assert_eq!(actual[0].source_rows, vec![7, 769]);
        assert!(actual[0].eligible && !actual[0].blocked);
        assert_eq!(actual[0].status, "review_required");
        assert_eq!(actual[0].reason, "pending_probe");
        assert!(actual[128].site.is_none() && actual[128].blocked);
        assert!(actual[129].site.is_none() && !actual[129].eligible);
        let first = build_probe(&reference, &mut actual.clone(), 1).unwrap();
        let prior = build_probe(&reference, &mut expected.clone(), 1).unwrap();
        assert_eq!(first.sequence, prior.sequence);
        assert_eq!(first.sites, prior.sites);
    }

