    #[test]
    fn first_probe_support_is_not_retested_or_overwritten_by_second_probe_calls() {
        let reference = "CAAAGTTTC";
        let mut reviews = vec![candidate(1, 4, "A"), candidate(5, 8, "T")];
        let first = build_probe(reference, &mut reviews, 1).unwrap();
        evaluate_probe(
            &first,
            &table(&[("1", "CAA", "CAAA", "6", "10")]),
            &mut reviews,
            3,
        );
        assert_eq!(reviews[0].selected, Some(3));
        assert_eq!(reviews[0].status, "support");
        let first_call = reviews[0].evidence.matched.clone();
        let first_reason = reviews[0].reason.clone();
        let second = build_probe(reference, &mut reviews, 2).unwrap();
        assert_eq!(
            second.sites.iter().map(|(i, _)| *i).collect::<Vec<_>>(),
            vec![1]
        );
        // This ordinary round also contains a conflicting call at the already
        // confirmed first locus; only second.sites may update repeat decisions.
        evaluate_probe(
            &second,
            &table(&[
                ("1", "CAAA", "CAA", "9", "10"),
                ("5", "GT", "GTTT", "9", "10"),
            ]),
            &mut reviews,
            4,
        );
        assert_eq!(reviews[0].selected, Some(3));
        assert_eq!(reviews[0].evidence.round, Some(3));
        assert_eq!(reviews[0].evidence.matched, first_call);
        assert_eq!(reviews[0].reason, first_reason);
        assert_eq!(reviews[1].selected, Some(3));
    }
