    #[test]
    fn repeat_matching_accepts_equivalent_native_anchor_positions_but_not_other_edits() {
        let site = Site {
            start: 1,
            end: 4,
            motif: "A".into(),
        };
        let reference = "CAAAG";
        for call in [
            VariantCall::high(1, "CAAA".into(), "CAAAA".into()),
            VariantCall::high(2, "A".into(), "AA".into()),
        ] {
            assert_eq!(call_copies(reference, &site, &call), Some(4));
        }
        assert_eq!(
            call_copies(
                reference,
                &site,
                &VariantCall::high(1, "CAAA".into(), "TAAAA".into())
            ),
            None
        );
        assert_eq!(
            call_copies(
                reference,
                &site,
                &VariantCall::high(5, "G".into(), "GG".into())
            ),
            None
        );
    }
