fn dna(seed:u64,n:usize)->String {let mut x=seed;(0..n).map(|_|{x=x.wrapping_mul(6364136223846793005).wrapping_add(1);b"ACGT"[(x>>62)as usize]as char}).collect()}
struct BoundaryScopeFixture {
    root: PathBuf,
    checked: PathBuf,
    details: PathBuf,
    resolved: PathBuf,
    source: PolishPaths,
    first_report: PathBuf,
    component: String,
    a: String,
    b: String,
}
impl BoundaryScopeFixture {
    fn new(component: &str) -> Self {
        let root = fs::canonicalize(root()).unwrap();
        let a = dna(7, 200);
        let b = dna(19, 200);
        let c = dna(31, 200);
        let checked = root.join("checked.gfa");
        fs::write(
            &checked,
            format!("S\ta\t{a}\nS\tb\t{b}\nS\tc\t{c}\nL\ta\t+\tb\t+\t0M\nL\tc\t+\tc\t+\t0M\n"),
        )
        .unwrap();
        let graph1 = root.join("merged_unresolved_subgraph_001.gfa");
        let graph2 = root.join("merged_unresolved_subgraph_002.gfa");
        fs::write(&graph1, format!("S\ta_b\t{a}{b}\n")).unwrap();
        fs::write(&graph2, format!("S\tc\t{c}\nL\tc\t+\tc\t+\t0M\n")).unwrap();
        let resolved = root.join("resolved_subgraphs.fasta");
        fs::write(
            &resolved,
            format!(">subgraph_001\n{a}{b}\n>subgraph_002\n{c}\n"),
        )
        .unwrap();
        let details = root.join("resolve_details.tsv");
        let mut text = format!("section\tid\tkey\tvalue\tnotes\nrun\t.\tchecked_draft_gfa\t{}\t\nrun\t.\tsplit_component_gfas\t{},{}\t\nrun\t.\tresolved_fasta\t{}\t\n", checked.display(), graph1.display(), graph2.display(), resolved.display());
        for (id, node) in [("subgraph_001", "a_b"), ("subgraph_002", "c")] {
            text.push_str(&format!("resolution\t{id}\toriented_nodes\t{node}+\t\nresolution\t{id}\tselected_circular\tfalse\t\nresolution\t{id}\tselected_order\t.\t\nresolution\t{id}\tscore_method\treference-placement-fallback\t\nalignment\t{id}\treverse_complemented\tfalse\t\nalignment\t{id}\trotation_step\t0\t\n"));
        }
        fs::write(&details, text).unwrap();
        let source = PolishPaths::new(&root.join("04.polish"), "mito", component, 2);
        let first = PolishPaths::new(&root.join("04.polish"), "mito", component, 1);
        let sequence = if component == "subgraph_001" {
            format!("{a}{b}")
        } else {
            c.clone()
        };
        for paths in [&first, &source] {
            paths.create_dirs().unwrap();
            fs::write(
                paths.validation_fasta(),
                format!(">{component}\n{sequence}\n"),
            )
            .unwrap();
            fs::write(&paths.report, format!("section\tname\tmetric\tvalue\nglobal\trun\torganelle\tmito\nglobal\trun\tsubgraph\t{component}\nglobal\trun\tvalidate_round\t{}\ninput\tdraft\tpath\t{}\ninput\tdraft\trecord_id\t{component}\noutput\tsubgraph\tdir\t{}\noutput\tworkflow_round\tdir\t{}\noutput\tvalidation_fasta\tpath\t{}\n", paths.validate_round, resolved.display(), paths.subgraph_dir.display(), paths.round_dir.display(), paths.validation_fasta().display())).unwrap();
        }
        Self {
            root,
            checked,
            details,
            resolved,
            source,
            first_report: first.report,
            component: component.into(),
            a,
            b,
        }
    }
    fn scope(&self) -> Result<(BTreeSet<String>, Vec<PathBuf>), OrgraftError> {
        let mut evidence = Vec::new();
        let nodes = graph_boundary::component_nodes(
            &self.checked,
            &self.details,
            &self.first_report,
            &self.source,
            "mito",
            &self.component,
            &mut evidence,
        )?;
        Ok((nodes, evidence))
    }
    fn reads(&self) -> PathBuf {
        let path = self.root.join("reads.fasta");
        let word = format!("{}C{}", &self.a[120..], &self.b[..80]);
        fs::write(
            &path,
            (0..24)
                .map(|i| format!(">r{i}\n{word}\n"))
                .collect::<String>(),
        )
        .unwrap();
        path
    }
    fn replace(path: &Path, before: &str, after: &str) {
        let text = fs::read_to_string(path).unwrap();
        assert!(text.contains(before));
        fs::write(path, text.replace(before, after)).unwrap();
    }
}
impl Drop for BoundaryScopeFixture {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.root);
    }
}

#[test]
fn graph_boundary_component_scope_excludes_foreign_candidates_and_keeps_native_lineage() {
    let f = BoundaryScopeFixture::new("subgraph_002");
    let reads = f.reads();
    let old = graph_boundary::automatic(
        f.source.validation_fasta(),
        &reads,
        &f.checked,
        None,
        &f.root.join("whole"),
    )
    .unwrap();
    assert!(old.review && old.proposal.is_none());
    let (nodes, evidence) = f.scope().unwrap();
    assert_eq!(nodes, BTreeSet::from(["c".into()]));
    let selected = graph_boundary::automatic(
        f.source.validation_fasta(),
        &reads,
        &f.checked,
        Some(&nodes),
        &f.root.join("scoped"),
    )
    .unwrap();
    assert!(!selected.review && selected.proposal.is_none());
    assert!(!f.root.join("scoped").exists());
    for path in [
        &f.checked,
        &f.details,
        &f.resolved,
        &f.first_report,
        &f.source.report,
        &f.root.join("merged_unresolved_subgraph_002.gfa"),
        &f.source.validation_fasta().to_path_buf(),
    ] {
        assert!(evidence.contains(path));
    }
    let f = BoundaryScopeFixture::new("subgraph_001");
    let (nodes, _) = f.scope().unwrap();
    assert_eq!(nodes, BTreeSet::from(["a".into(), "b".into()]));
    let reads = f.reads();
    let old = graph_boundary::automatic(
        f.source.validation_fasta(),
        &reads,
        &f.checked,
        None,
        &f.root.join("whole"),
    )
    .unwrap();
    let new = graph_boundary::automatic(
        f.source.validation_fasta(),
        &reads,
        &f.checked,
        Some(&nodes),
        &f.root.join("scoped"),
    )
    .unwrap();
    assert!(!new.review);
    assert_eq!(
        fs::read(new.proposal.unwrap()).unwrap(),
        fs::read(old.proposal.unwrap()).unwrap()
    );
    assert_eq!(
        fs::read(f.root.join("scoped/junction.tsv")).unwrap(),
        fs::read(f.root.join("whole/junction.tsv")).unwrap()
    );
    assert_eq!(
        fs::read(f.root.join("scoped/read_support.tsv")).unwrap(),
        fs::read(f.root.join("whole/read_support.tsv")).unwrap()
    );
}

#[test]
fn graph_boundary_component_scope_rejects_wrong_or_incomplete_source_identity() {
    for mutation in 0..8 {
        let f = BoundaryScopeFixture::new("subgraph_001");
        match mutation {
            0 => BoundaryScopeFixture::replace(
                &f.details,
                "merged_unresolved_subgraph_001.gfa",
                "wrong_component.gfa",
            ),
            1 => BoundaryScopeFixture::replace(
                &f.root.join("merged_unresolved_subgraph_001.gfa"),
                &f.a,
                &dna(71, 200),
            ),
            2 => fs::write(
                f.root.join("merged_unresolved_subgraph_001.gfa"),
                format!("S\ta\t{}\n", f.a),
            )
            .unwrap(),
            3 => BoundaryScopeFixture::replace(
                &f.first_report,
                "record_id\tsubgraph_001",
                "record_id\tsubgraph_002",
            ),
            4 => BoundaryScopeFixture::replace(
                &f.source.report,
                "subgraph\tsubgraph_001",
                "subgraph\tsubgraph_002",
            ),
            5 => BoundaryScopeFixture::replace(
                &f.source.report,
                "validate_round\t2",
                "validate_round\t1",
            ),
            6 => BoundaryScopeFixture::replace(
                f.source.validation_fasta(),
                ">subgraph_001",
                ">subgraph_002",
            ),
            7 => {
                let other = f.root.join("other_resolved.fasta");
                fs::write(&other, fs::read(&f.resolved).unwrap()).unwrap();
                BoundaryScopeFixture::replace(
                    &f.first_report,
                    f.resolved.to_str().unwrap(),
                    other.to_str().unwrap(),
                );
            }
            _ => unreachable!(),
        }
        assert!(f.scope().is_err(), "mutation {mutation}");
    }
    let f = BoundaryScopeFixture::new("subgraph_001");
    let original = fs::read_to_string(&f.details).unwrap();
    let row = original
        .lines()
        .find(|line| line.contains("\tsplit_component_gfas\t"))
        .unwrap();
    fs::write(&f.details, format!("{original}{row}\n")).unwrap();
    assert!(f.scope().is_err());
}

#[test]
fn graph_boundary_component_scope_keeps_whole_checked_uniqueness() {
    let f = BoundaryScopeFixture::new("subgraph_001");
    let duplicate = format!("{}{}", dna(99, 160), &f.a[160..]);
    let mut checked = fs::read_to_string(&f.checked).unwrap();
    checked.push_str(&format!("S\td\t{duplicate}\nL\td\t+\td\t+\t0M\n"));
    fs::write(&f.checked, checked).unwrap();
    let (nodes, _) = f.scope().unwrap();
    let result = graph_boundary::automatic(
        f.source.validation_fasta(),
        &f.reads(),
        &f.checked,
        Some(&nodes),
        &f.root.join("scoped"),
    )
    .unwrap();
    assert!(!result.review && result.proposal.is_none());
    assert!(graph_boundary::automatic(
        f.source.validation_fasta(),
        &f.reads(),
        &f.checked,
        Some(&BTreeSet::from(["absent".into()])),
        &f.root.join("absent")
    )
    .is_err());
}

#[test]
fn one_base_junction_uses_all_reads_and_requires_current_path(){
    let root=root();let a=dna(7,200);let b=dna(19,200);let graph=root.join("input.gfa");
    fs::write(&graph,format!("S\ta\t{a}\nS\tb\t{b}\nL\ta\t+\tb\t+\t0M\n")).unwrap();
    let source=root.join("source.fasta");let reads=root.join("reads.fasta");fs::write(&source,format!(">c\n{a}{b}\n")).unwrap();
    let word=format!("{}C{}",&a[120..],&b[..80]);
    fs::write(&reads,(0..24).map(|i|format!(">r{i}\n{word}\n")).collect::<String>()+">unknown\nNNNNNNNNNNNNNNNNNNNNNNNN\n").unwrap();
    let result=graph_boundary::automatic(&source,&reads,&graph,None,&root.join("test")).unwrap();
    assert!(!result.review);assert_eq!(first_sequence(&result.proposal.unwrap()).unwrap(),format!("{a}C{b}"));
    let evidence=fs::read_to_string(root.join("test/read_support.tsv")).unwrap();assert!(evidence.contains("unknown\t."));assert_eq!(evidence.lines().count(),26);
    fs::write(&source,format!(">c\n{b}{a}\n")).unwrap();
    let result=graph_boundary::automatic(&source,&reads,&graph,None,&root.join("missing")).unwrap();assert!(result.review);assert!(result.proposal.is_none());
    assert!(fs::read_to_string(root.join("missing/junction.tsv")).unwrap().contains("requires_graph_review"));
    fs::remove_dir_all(root).unwrap();
}
#[test]
fn a_zero_base_control_prevents_one_base_selection(){
    let root=root();let a=dna(7,200);let b=dna(19,200);let graph=root.join("input.gfa");let source=root.join("source.fasta");let reads=root.join("reads.fasta");
    fs::write(&graph,format!("S\ta\t{a}\nS\tb\t{b}\n")).unwrap();fs::write(&source,format!(">c\n{a}{b}\n")).unwrap();
    fs::write(&reads,(0..24).map(|i|format!(">r{i}\n{}C{}\n",&a[120..],&b[..80])).collect::<String>()+&format!(">control\n{}{}\n",&a[120..],&b[..80])).unwrap();
    let result=graph_boundary::automatic(&source,&reads,&graph,None,&root.join("test")).unwrap();assert!(result.proposal.is_none());assert!(!result.review);
    fs::remove_dir_all(root).unwrap();
}
#[test]
fn adjacent_repeat_models_come_from_native_alleles_not_sample_identity(){
    let root=root();let sequence="AGGCCCCCCCCTCCCCCCCCGTA";let table=root.join("variants.tsv");
    fs::write(&table,"pos\tref\talt\tcounts\tdepth\ttype\n3\tGCCCCCCCC\tGCCCCCCC\t16\t40\tInDel,homopolymer\n12\tTCCCCCCCC\tTCCCCCCC\t17\t40\tInDel,homopolymer\n").unwrap();
    let pairs=compressed_candidates(sequence,&table,&[]).unwrap();assert_eq!(pairs.len(),1);assert_eq!((pairs[0].start,pairs[0].end,pairs[0].left_alt,pairs[0].right_alt),(3,20,7,7));
    fs::remove_dir_all(root).unwrap();
}
